import { createContext, useContext, useState, useCallback, type ReactNode } from 'react';

interface ConversationContextValue {
  sidebarOpen: boolean;
  setSidebarOpen: (open: boolean) => void;
  toggleSidebar: () => void;
  contextPanelOpen: boolean;
  setContextPanelOpen: (open: boolean) => void;
  toggleContextPanel: () => void;
  streaming: boolean;
  setStreaming: (v: boolean) => void;
}

const ConversationContext = createContext<ConversationContextValue | null>(null);

export function useConversationContext() {
  const ctx = useContext(ConversationContext);
  if (!ctx) throw new Error('useConversationContext must be used within ConversationLayout');
  return ctx;
}

export function ConversationContextProvider({ children }: { children: ReactNode }) {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [contextPanelOpen, setContextPanelOpen] = useState(false);
  const [streaming, setStreaming] = useState(false);

  const toggleSidebar = useCallback(() => setSidebarOpen((v) => !v), []);
  const toggleContextPanel = useCallback(() => setContextPanelOpen((v) => !v), []);

  return (
    <ConversationContext.Provider
      value={{
        sidebarOpen,
        setSidebarOpen,
        toggleSidebar,
        contextPanelOpen,
        setContextPanelOpen,
        toggleContextPanel,
        streaming,
        setStreaming,
      }}
    >
      {children}
    </ConversationContext.Provider>
  );
}

import { useState, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Clock, Star } from 'lucide-react';
import { HistoryHeader } from './HistoryHeader';
import { HistorySearch } from './HistorySearch';
import { HistoryFilters } from './HistoryFilters';
import { HistoryTimeline } from './HistoryTimeline';
import { HistoryDetailDrawer } from './HistoryDetailDrawer';
import { HistoryEmptyState } from './HistoryEmptyState';
import { HistoryLoading } from './HistoryLoading';
import { HistoryErrorCard } from './HistoryErrorCard';
import { type HistoryItem, type ActivityCategory } from './HistoryTypes';
import { useAIReportHistory } from '../../../services/reporting-ai-hooks';

function mapReportToHistoryItem(report: any): HistoryItem {
  const date = report.generationDate ? new Date(report.generationDate) : new Date();
  const now = new Date();
  const diffDays = Math.floor((now.getTime() - date.getTime()) / (1000 * 60 * 60 * 24));
  let label = 'Today';
  if (diffDays === 1) label = 'Yesterday';
  else if (diffDays <= 7) label = `${diffDays} days ago`;
  else if (diffDays <= 30) label = 'Last week';
  else label = 'Last month';

  return {
    id: report.reportId,
    type: 'executive-summary',
    title: report.title,
    description: report.executiveSummary?.slice(0, 120) ?? 'Executive report',
    category: 'reports',
    workspace: 'Workspace',
    department: 'Department',
    date: label,
    time: date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    favorite: false,
    status: report.approvalStatus === 'APPROVED' ? 'completed' : 'draft',
  };
}

export function HistoryPage({
  workspaceId,
}: {
  workspaceId?: string;
}) {
  const [searchParams] = useSearchParams();
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<ActivityCategory | 'all'>('all');
  const [timeFilter, setTimeFilter] = useState('all-time');
  const [selectedItem, setSelectedItem] = useState<HistoryItem | null>(null);
  const [favorites, setFavorites] = useState<Set<string>>(new Set());
  const [error, setError] = useState<string | null>(null);
  const [searches, setSearches] = useState<string[]>([]);

  const { data: reportHistory, isLoading, isError } = useAIReportHistory(workspaceId);

  const allItems = useMemo(() => {
    const items: HistoryItem[] = [];
    if (reportHistory?.content) {
      items.push(...reportHistory.content.map(mapReportToHistoryItem));
    }
    return items;
  }, [reportHistory]);

  const items = useMemo(() => {
    let list = [...allItems];

    if (categoryFilter === 'favorites') {
      list = list.filter((i) => favorites.has(i.id));
    } else if (categoryFilter !== 'all') {
      list = list.filter((i) => i.category === categoryFilter);
    }

    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      list = list.filter(
        (i) =>
          i.title.toLowerCase().includes(q) ||
          i.description.toLowerCase().includes(q) ||
          i.workspace.toLowerCase().includes(q),
      );
    }

    return list;
  }, [allItems, categoryFilter, searchQuery, favorites]);

  const grouped = useMemo(() => {
    const groups: Record<string, HistoryItem[]> = {};
    const dateOrder = ['Today', 'Yesterday', '3 days ago', '4 days ago', '5 days ago', '6 days ago', 'Last week', 'Last month'];

    for (const item of items) {
      if (!groups[item.date]) groups[item.date] = [];
      groups[item.date].push(item);
    }

    return dateOrder.filter((d) => groups[d]).map((d) => ({ label: d, items: groups[d] }));
  }, [items]);

  function handleToggleFavorite(id: string) {
    setFavorites((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  function handleSearch(query: string) {
    setSearchQuery(query);
    if (query.trim() && !searches.includes(query.trim())) {
      setSearches((prev) => [query.trim(), ...prev].slice(0, 5));
    }
  }

  const favoriteItems = useMemo(() => allItems.filter((i) => favorites.has(i.id)), [allItems, favorites]);

  if (isLoading) return <HistoryLoading />;

  if (isError || error) {
    return (
      <div className="flex flex-col gap-6">
        <HistoryHeader />
        <HistoryErrorCard message={error ?? 'Failed to load history'} onRetry={() => setError(null)} onDismiss={() => setError(null)} />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 animate-fade-in">
      <HistoryHeader />

      <HistorySearch
        query={searchQuery}
        onQueryChange={handleSearch}
        onClearSearch={() => setSearchQuery('')}
        recentSearches={searches}
      />

      <HistoryFilters
        categoryActive={categoryFilter}
        timeActive={timeFilter}
        onCategoryChange={setCategoryFilter}
        onTimeChange={setTimeFilter}
      />

      {categoryFilter === 'favorites' && favoriteItems.length > 0 && (
        <section className="flex flex-col gap-4">
          <div className="flex items-center gap-2">
            <Star className="h-4 w-4 text-text-tertiary" />
            <h2 className="text-section font-semibold text-text-primary">Favorites</h2>
          </div>
          <HistoryTimeline
            groups={[{ label: 'Favorites', items: favoriteItems }]}
            onItemClick={setSelectedItem}
            onToggleFavorite={handleToggleFavorite}
            favorites={favorites}
          />
        </section>
      )}

      {(categoryFilter !== 'favorites' || !favoriteItems.length) && (
        <>
          {grouped.length === 0 ? (
            <HistoryEmptyState
              variant={searchQuery ? 'no-results' : categoryFilter !== 'all' ? 'no-category' : 'no-history'}
              searchQuery={searchQuery}
              onClearSearch={() => setSearchQuery('')}
              onStartAction={() => {}}
            />
          ) : (
            <div className="flex flex-col gap-4">
              {searchQuery && (
                <div className="flex items-center gap-2">
                  <Clock className="h-4 w-4 text-text-tertiary" />
                  <p className="text-caption text-text-secondary">
                    {items.length} result{items.length !== 1 ? 's' : ''} for &ldquo;{searchQuery}&rdquo;
                  </p>
                </div>
              )}
              <HistoryTimeline
                groups={grouped}
                onItemClick={setSelectedItem}
                onToggleFavorite={handleToggleFavorite}
                favorites={favorites}
              />
            </div>
          )}
        </>
      )}

      {selectedItem && (
        <HistoryDetailDrawer
          item={selectedItem}
          isFavorite={favorites.has(selectedItem.id)}
          onClose={() => setSelectedItem(null)}
          onToggleFavorite={() => handleToggleFavorite(selectedItem.id)}
          onReopen={() => {}}
          onCopy={() => {}}
          onDelete={() => {}}
        />
      )}
    </div>
  );
}

import { useState, useMemo } from 'react';
import { Clock, Star, Sparkles } from 'lucide-react';
import { PromptHeader } from './PromptHeader';
import { PromptSearch } from './PromptSearch';
import { PromptCategoryNav, type PromptCategoryNavProps } from './PromptCategoryNav';
import { PromptFeatured } from './PromptFeatured';
import { PromptGrid } from './PromptGrid';
import { PromptDetailDrawer } from './PromptDetailDrawer';
import { PromptRunModal } from './PromptRunModal';
import { PromptEmptyState } from './PromptEmptyState';
import { PromptLoading } from './PromptLoading';
import { PromptErrorCard } from './PromptErrorCard';
import type { Prompt, PromptCategoryId } from './PromptTypes';

const emptyPrompts: Prompt[] = [];

export function PromptLibraryPage() {
  const [activeCategory, setActiveCategory] = useState<PromptCategoryId | 'all'>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedPrompt, setSelectedPrompt] = useState<Prompt | null>(null);
  const [runPrompt, setRunPrompt] = useState<Prompt | null>(null);
  const [favorites, setFavorites] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searches, setSearches] = useState<string[]>([]);

  const prompts = emptyPrompts;

  const filtered = useMemo(() => {
    let items = [...prompts];
    if (activeCategory === 'favorites') {
      items = items.filter((p) => favorites.has(p.id));
    } else if (activeCategory !== 'all') {
      items = items.filter((p) => p.category === activeCategory);
    }
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      items = items.filter(
        (p) =>
          p.title.toLowerCase().includes(q) ||
          p.description.toLowerCase().includes(q) ||
          p.tags.some((t) => t.toLowerCase().includes(q)),
      );
    }
    return items;
  }, [activeCategory, searchQuery, favorites]);

  const featured = useMemo(() => prompts.filter((p) => p.featured), []);
  const recent = useMemo(() => [], []);
  const favoritePrompts = useMemo(() => prompts.filter((p) => favorites.has(p.id)), [favorites]);

  function handleToggleFavorite(id: string) {
    setFavorites((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  function handleSearch(query: string) {
    setSearchQuery(query);
    if (query.trim() && !searches.includes(query.trim())) {
      setSearches((prev) => [query.trim(), ...prev].slice(0, 5));
    }
  }

  const handleCategoryChange: PromptCategoryNavProps['onChange'] = (cat) => {
    setActiveCategory(cat);
    setSearchQuery('');
  };

  if (loading) return <PromptLoading />;

  if (error) {
    return (
      <div className="flex flex-col gap-6">
        <PromptHeader onSearch={() => {}} />
        <PromptErrorCard message={error} onRetry={() => setError(null)} onDismiss={() => setError(null)} />
      </div>
    );
  }

  const showFavorites = activeCategory === 'all' && !searchQuery && favoritePrompts.length > 0;
  const showRecent = activeCategory === 'all' && !searchQuery && recent.length > 0;
  const showFeatured = activeCategory === 'all' && !searchQuery;

  return (
    <div className="flex flex-col gap-8 animate-fade-in">
      <PromptHeader searches={searches} onSearch={handleSearch} />

      <PromptSearch
        query={searchQuery}
        onQueryChange={handleSearch}
        recentSearches={searches}
        popularPrompts={prompts.filter((p) => p.featured).map((p) => p.title)}
        onClearSearch={() => setSearchQuery('')}
      />

      <PromptCategoryNav active={activeCategory} onChange={handleCategoryChange} />

      {showFeatured && (
        <PromptFeatured prompts={featured} onPreview={setSelectedPrompt} onRun={setRunPrompt} onToggleFavorite={handleToggleFavorite} favorites={favorites} />
      )}

      {showRecent && (
        <section className="flex flex-col gap-4">
          <div className="flex items-center gap-2">
            <Clock className="h-4 w-4 text-text-tertiary" />
            <h2 className="text-section font-semibold text-text-primary">Recently Used</h2>
          </div>
          <div className="flex gap-3 overflow-x-auto pb-2 -mx-1 px-1 scrollbar-thin">
            {recent.map((prompt) => (
              <div key={prompt.id} className="shrink-0 w-64 rounded-xl border border-border-subtle bg-surface p-4 hover:shadow-cx-sm hover:-translate-y-0.5 transition-all duration-150">
                <p className="text-caption font-medium text-text-primary truncate">{prompt.title}</p>
                <p className="text-2xs text-text-tertiary mt-1">{prompt.lastUsed}</p>
                <div className="mt-3 flex gap-2">
                  <button
                    type="button"
                    onClick={() => setRunPrompt(prompt)}
                    className="flex-1 rounded-lg bg-accent-600 px-3 py-1.5 text-2xs font-medium text-white hover:bg-accent-700 transition-colors"
                  >
                    Run
                  </button>
                  <button
                    type="button"
                    onClick={() => setSelectedPrompt(prompt)}
                    className="rounded-lg border border-border-subtle px-3 py-1.5 text-2xs font-medium text-text-secondary hover:bg-surface-2 transition-colors"
                  >
                    Preview
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {showFavorites && (
        <section className="flex flex-col gap-4">
          <div className="flex items-center gap-2">
            <Star className="h-4 w-4 text-text-tertiary" />
            <h2 className="text-section font-semibold text-text-primary">Favorites</h2>
          </div>
          <PromptGrid
            prompts={favoritePrompts}
            onPreview={setSelectedPrompt}
            onRun={setRunPrompt}
            onToggleFavorite={handleToggleFavorite}
            favorites={favorites}
          />
        </section>
      )}

      {(activeCategory !== 'all' || searchQuery) && filtered.length === 0 ? (
        <PromptEmptyState
          variant={searchQuery ? 'no-results' : 'no-category'}
          searchQuery={searchQuery}
          category={activeCategory !== 'all' ? activeCategory : undefined}
          onClearSearch={() => setSearchQuery('')}
        />
      ) : (
        <section className="flex flex-col gap-4">
          {(activeCategory !== 'all' || searchQuery) && (
            <div className="flex items-center gap-2">
              <Sparkles className="h-4 w-4 text-text-tertiary" />
              <h2 className="text-section font-semibold text-text-primary">
                {searchQuery ? `Results for "${searchQuery}"` : 'All Prompts'}
              </h2>
              <span className="text-caption text-text-tertiary">{filtered.length}</span>
            </div>
          )}
          {!showFavorites && !showRecent && !showFeatured && (
            <PromptGrid
              prompts={filtered}
              onPreview={setSelectedPrompt}
              onRun={setRunPrompt}
              onToggleFavorite={handleToggleFavorite}
              favorites={favorites}
            />
          )}
        </section>
      )}

      {selectedPrompt && (
        <PromptDetailDrawer
          prompt={selectedPrompt}
          isFavorite={favorites.has(selectedPrompt.id)}
          onClose={() => setSelectedPrompt(null)}
          onToggleFavorite={() => handleToggleFavorite(selectedPrompt.id)}
          onRun={() => { setRunPrompt(selectedPrompt); setSelectedPrompt(null); }}
        />
      )}

      {runPrompt && (
        <PromptRunModal
          prompt={runPrompt}
          onClose={() => setRunPrompt(null)}
          onRun={() => {}}
        />
      )}
    </div>
  );
}

