function isItemActive(item: NavItem, activeId: string): boolean {
  if (item.id === activeId) return true;
  return item.children?.some((c) => c.id === activeId) ?? false;
}

function NavLink({
  item,
  collapsed,
  activeId,
  onNavigate,
  expandedSections,
  setExpandedSections,
