                          className="px-4 py-3 text-center text-caption font-semibold text-text-secondary min-w-[120px]"
                        >
                          {role.name}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {permissions?.map((perm) => (
                      <tr key={perm.id} className="border-b border-border-subtle hover:bg-surface-2">
                        <td className="px-4 py-3">
                          <div>
                            <p className="text-body font-medium text-text-primary">{perm.displayName}</p>
                            <p className="text-2xs text-text-tertiary">{perm.code}</p>
                          </div>
                        </td>
                        {roles.map((role) => {
                          const granted = role.permissions?.includes(perm.code);
                          return (
                            <td key={`${perm.id}-${role.id}`} className="px-4 py-3 text-center">
                              {granted ? (
                                <Check className="h-4 w-4 text-success-500 mx-auto" />
                              ) : (
                                <XIcon className="h-4 w-4 text-text-tertiary mx-auto" />
                              )}
                            </td>
                          );
                        })}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            <div className="flex items-center gap-2 mt-4 pt-3 border-t border-border-subtle text-caption text-text-tertiary">
              <Info className="h-3.5 w-3.5" />
              Permission assignments are managed through role configuration on the backend
            </div>
          </CardBody>
        </Card>
      )}
            <div className="flex items-center gap-2 mt-4 pt-3 border-t border-border-subtle text-caption text-text-tertiary">
              <Info className="h-3.5 w-3.5" />
              Permission assignments are managed through role configuration on the backend
            </div>
          </CardBody>
        </Card>
      )}

      <PermissionDetailsModal
        permission={selectedPermission}
        onClose={() => setSelectedPermission(null)}
      />
    </div>
  );
}

function PermissionDetailsModal({
  permission,
  onClose,
}: {
  permission: PermissionResponse | null;
  onClose: () => void;
}) {
  return (
    <Modal open={!!permission} onClose={onClose} title="Permission Details" size="md">
      {permission && (
        <div className="space-y-6">
          <div className="flex items-start gap-3">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-accent-50 text-accent-600 dark:bg-accent-100 dark:text-accent-300">
              <Shield className="h-5 w-5" />
            </div>
            <div>
              <h3 className="text-section font-semibold text-text-primary">{permission.displayName}</h3>
              <p className="text-body text-text-secondary mt-1">{permission.description}</p>
            </div>
          </div>

          <div className="bg-surface-2 rounded-lg p-3">
            <p className="text-2xs text-text-tertiary mb-1">Permission Code</p>
            <code className="text-body font-mono text-text-primary">{permission.code}</code>
          </div>

          <div className="bg-surface-2 rounded-lg p-3">
            <p className="text-2xs text-text-tertiary mb-1">Permission ID</p>
            <code className="text-body font-mono text-text-primary">{permission.id}</code>
          </div>
        </div>
      )}
    </Modal>
  );
}

// User Management Types
export type UserStatus = 'active' | 'inactive' | 'pending' | 'suspended';
export type UserRole = 'admin' | 'manager' | 'user' | 'viewer';

export interface User {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  status: UserStatus;
  role: UserRole;
  department?: string;
  team?: string;
  workspace: string;
  lastLogin?: string;
  createdAt: string;
  updatedAt: string;
  avatar?: string;
  avatarTone?: number;
  permissions: string[];
}

export interface UserProfile extends User {
  phone?: string;
  jobTitle?: string;
  location?: string;
  bio?: string;
  assignedProjects: string[];
  assignedTasks: string[];
  teams: string[];
  departments: string[];
}

// Role Management Types
export type PermissionScope = 'workspace' | 'department' | 'team' | 'project' | 'personal';

export interface Permission {
  id: string;
  name: string;
  description: string;
  module: string;
  scope: PermissionScope;
  action: string;
  resource: string;
}

export interface Role {
  id: string;
  name: string;
  description: string;
  workspace?: string;
  permissions: Permission[];
  usersCount: number;
  isBuiltIn: boolean;
  createdAt: string;
  updatedAt: string;
  createdBy?: string;
}

export interface RoleWithUsers extends Role {
  assignedUsers: User[];
}

// Permission Management Types
export interface PermissionModule {
  name: string;
  description: string;
  permissions: Permission[];
}

export interface PermissionMatrix {
  roles: Role[];
  modules: PermissionModule[];
  assignments: Record<string, Record<string, boolean>>; // roleId -> permissionId -> assigned
}

// Audit Log Types
export type AuditAction = 
  | 'create' | 'read' | 'update' | 'delete'
  | 'login' | 'logout' | 'import' | 'export'
  | 'assign' | 'unassign' | 'grant' | 'revoke'
  | 'activate' | 'deactivate' | 'suspend' | 'restore';

export type AuditModule = 
  | 'users' | 'roles' | 'permissions' | 'workspace'
  | 'organization' | 'department' | 'team' | 'member'
  | 'project' | 'task' | 'document' | 'knowledge'
  | 'notification' | 'report' | 'settings';

export type AuditSeverity = 'info' | 'warning' | 'critical';
export type AuditResult = 'success' | 'failure' | 'partial';

export interface AuditLog {
  id: string;
  timestamp: string;
  userId: string;
  userName: string;
  action: AuditAction;
  module: AuditModule;
  entityType: string;
  entityId: string;
  entityName?: string;
  workspace?: string;
  department?: string;
  severity: AuditSeverity;
  result: AuditResult;
  message: string;
  ipAddress?: string;
  userAgent?: string;
  metadata?: Record<string, any>;
  beforeState?: Record<string, any>;
  afterState?: Record<string, any>;
}

// Filter Types
export interface UserFilter {
  search?: string;
  status?: UserStatus;
  role?: UserRole;
  department?: string;
  team?: string;
  workspace?: string;
  dateJoinedFrom?: string;
  dateJoinedTo?: string;
  sortBy?: 'name' | 'email' | 'joined' | 'lastLogin';
  sortOrder?: 'asc' | 'desc';
}

export interface AuditFilter {
  search?: string;
  user?: string;
  module?: AuditModule;
  action?: AuditAction;
  workspace?: string;
  department?: string;
  severity?: AuditSeverity;
  result?: AuditResult;
  dateFrom?: string;
  dateTo?: string;
  sortBy?: 'timestamp' | 'user' | 'action';
  sortOrder?: 'asc' | 'desc';
}

// Permission Check Type
export interface PermissionCheck {
  module: string;
  action: string;
  resource?: string;
  granted: boolean;
}

// Administration Panel Types
export interface AdminStats {
  totalUsers: number;
  activeUsers: number;
  inactiveUsers: number;
  totalRoles: number;
  totalPermissions: number;
  recentAuditLogs: AuditLog[];
  recentActions: AuditLog[];
}

