function MemberCard({ member }: { member: MemberProfile }) {
  const statusColor: Record<typeof member.status, string> = {
    active: 'success',
    away: 'warning',
    offline: 'neutral',
    inactive: 'danger',
  };

  const availabilityColor: Record<typeof member.availability, string> = {
    available: 'success',
    busy: 'danger',
    away: 'warning',
    offline: 'neutral',
