        </div>

        <div className="flex flex-wrap gap-4 text-caption text-text-secondary">
          <span className="flex items-center gap-1">
            <FileIcon className="h-3 w-3" />
            {formatLabel[exp.format]}
          </span>
          <span>{(exp.fileSize / 1024).toFixed(1)} KB</span>
          <span className="flex items-center gap-1">
